1	import {jest} from '@jest/globals';
2	import {WebSocket} from 'ws';
3	import {createMessageHandler} from './messageHandler.js';
4	import {createChatOrchestrator, TOOL_BUDGET_EXHAUSTED} from '../../orchestration/chatOrchestrator.js';
5	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
6	import {ToolRegistry} from '../../orchestration/tools/registry.js';
7	import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
8	import type {AIProvider, MessageChunk, ToolCall} from '../../types/ai.js';
9	import {AIError} from '../../types/ai.js';
10	import type {ChatSession, SessionEntry} from '../../types/session.js';
11	import type {OutgoingMessage} from '../../types/messages.js';
12	import {PerSessionLock} from '../../shared/perSessionLock.js';
13	import {deferred} from '../wsTestSupport.js';
14	
15	// The frames, in order, are the contract - above all for suppression, which retracts.
16	
17	// One line per frame; entries carry generated timestamps no assertion should read.
18	const wire = (sent: OutgoingMessage[]): string[] =>
19	  sent.map(frame => {
20	    if (frame.type === 'entry_upsert') {
21	      const content = 'content' in frame.entry ? frame.entry.content : '';
22	      return `upsert ${frame.index} ${frame.entry.role} ${JSON.stringify(content)}`;
23	    }
24	    if (frame.type === 'entry_delta') return `delta ${frame.index} ${JSON.stringify(frame.delta)}`;
25	    if (frame.type === 'entry_commit') return `commit ${frame.index}`;
26	    if (frame.type === 'entry_skip') return `skip ${frame.index}`;
27	    if (frame.type === 'error') return `error ${frame.code}`;
28	    if (frame.type === 'pong') return `pong ${frame.timestamp}`;
29	    return frame.type;
30	  });
31	
32	const text = (value: string): MessageChunk => ({type: 'text', text: value});
33	const STOP: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
34	const SUPPRESS = {type: 'suppress_output'} as unknown as MessageChunk;
35	
36	interface StreamScript {
37	  failWith?: Error;
38	  pauseAfter?: {chunks: number; until: Promise<void>};
39	}
40	
41	const harness = (chunks: MessageChunk[], {failWith, pauseAfter}: StreamScript = {}) => {
42	  const sent: OutgoingMessage[] = [];
43	  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
44	
45	  const stream = async function* (): AsyncGenerator<MessageChunk> {
46	    for (const [position, chunk] of chunks.entries()) {
47	      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
48	      yield chunk;
49	    }
50	    if (failWith) throw failWith;
51	  };
52	
53	  const processMessageStream = jest.fn(stream);
54	  const orchestrator = {processMessageStream} as unknown as ChatOrchestrator;
55	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
56	
57	  const handle = createMessageHandler(orchestrator);
58	
59	  return {
60	    session,
61	    processMessageStream,
62	    sent,
63	    frames: () => wire(sent),
64	    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
65	      handle(ws, session, raw, signal),
66	  };
67	};
68	
69	describe('the websocket message handler', () => {
70	  describe('dispatch', () => {
71	    it('rejects an unparseable message and never starts a stream', async () => {
72	      const h = harness([]);
73	
74	      await h.send({type: 'nonsense'});
75	
76	      const {calls} = h.processMessageStream.mock;
77	
78	      expect({frames: h.frames(), streams: calls.length}).toEqual({frames: ['error INVALID_MESSAGE'], streams: 0});
79	    });
80	
81	    it('answers a ping with the timestamp it was given', async () => {
82	      const h = harness([]);
83	
84	      await h.send({type: 'ping', timestamp: 1234});
85	
86	      expect(h.frames()).toEqual(['pong 1234']);
87	    });
88	  });
89	
90	  describe('a plain assistant reply', () => {
91	    it('sends the user entry, then the assistant entry, its delta, its commit and stream_end', async () => {
92	      const h = harness([text('hi there'), STOP]);
